import sys

def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        for d in divisors:
            current = d
            for e in range(1, exp + 1):
                current *= p
                temp.append(current)
        divisors += temp
    return divisors

def main():
    N = int(sys.stdin.readline())
    if N == 1:
        print(0)
        return

    N_minus_1 = N - 1
    factors_N = factorize(N)
    factors_N_minus_1 = factorize(N_minus_1)

    divisors_N = generate_divisors(factors_N)
    divisors_N_minus_1 = generate_divisors(factors_N_minus_1)

    count1 = 0
    for d in divisors_N_minus_1:
        if d >= 2:
            count1 += 1

