    for bit in range(max_bit + 1):
        cnt = 0
        for a in A:
            if (a >> bit) & 1:
                cnt += 1
        cnt_ones[bit] = cnt

    @lru_cache(maxsize=None)
    def dp(bit, tight):
        if bit < 0:
            return 0
        max_bit_val = (K >> bit) & 1 if tight else 1
        res = 0
