            if tight and x > max_bit_val:
                continue
            if x == 1:
                contrib = (N - cnt_ones[bit]) * (1 << bit)
            else:
                contrib = cnt_ones[bit] * (1 << bit)
            new_tight = tight and (x == max_bit_val)
            res = max(res, contrib + dp(bit - 1, new_tight))
        return res

