def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    H = list(map(int, input[2:2+N]))

    # Initialize dp: dp[i][k] is a dictionary of h_prev to min_sum
    dp = [[{} for _ in range(K+1)] for _ in range(N+1)]

    # First column
    original_h = H[0]
    dp[1][0][original_h] = original_h
    if K >= 1:
        dp[1][1][0] = 0

    for i in range(2, N+1):
        for k_prev in range(K+1):
            for h_prev_prev in list(dp[i-1][k_prev].keys()):
                # Option 1: do not modify column i
                new_h = H[i-1]
                contribution = max(0, new_h - h_prev_prev)
                new_sum = dp[i-1][k_prev][h_prev_prev] + contribution
                if new_h in dp[i][k_prev]:
                    if new_sum < dp[i][k_prev][new_h]:
                        dp[i][k_prev][new_h] = new_sum
                else:
                    dp[i][k_prev][new_h] = new_sum
                # Option 2: modify column i
                new_h_mod = h_prev_prev
                contribution_mod = 0
                new_sum_mod = dp[i-1][k_prev][h_prev_prev] + contribution_mod
                if k_prev + 1 <= K:
                    if new_h_mod in dp[i][k_prev + 1]:
                        if new_sum_mod < dp[i][k_prev + 1][new_h_mod]:
                            dp[i][k_prev + 1][new_h_mod] = new_sum_mod
                    else:
                        dp[i][k_prev + 1][new_h_mod] = new_sum_mod

    min_total = float('inf')
    for k in range(K+1):
        if dp[N][k]:
            current_min = min(dp[N][k].values())
            if current_min < min_total:
                min_total = current_min
    print(min_total)

